package com.clara.workspace.runtime;
import com.clara.kernel.*;import com.clara.workspace.api.*;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class FileSystemWorkspaceWriterTest {@Rule public final TemporaryFolder folder=new TemporaryFolder();private Path root;private WorkspacePolicy policy;private WorkspaceRef previewWorkspace,applyWorkspace;private DefaultWorkspaceTextService text;
 @Before public void setUp()throws Exception{root=folder.newFolder("workspace").toPath();policy=new WorkspacePolicy(Collections.singleton(".txt"),Collections.<String>emptySet(),Collections.<String>emptySet(),20,10000,50000,false);previewWorkspace=new WorkspaceRef("w","t","run",root.toAbsolutePath(),WorkspaceAccessMode.PREVIEW_WRITE);applyWorkspace=new WorkspaceRef("w","t","run",root.toAbsolutePath(),WorkspaceAccessMode.APPLY_WRITE);text=new DefaultWorkspaceTextService(new FileSystemWorkspaceReader(policy),policy);}
 @Test public void appliesApprovedChangeAtomicallyAndKeepsBackup()throws Exception{Files.write(root.resolve("a.txt"),"old".getBytes(StandardCharsets.UTF_8));ChangeSet set=replace(previewWorkspace,"old","new");FileSystemWorkspaceWriter writer=new FileSystemWorkspaceWriter(policy);ChangePreview preview=writer.preview(previewWorkspace,set);Approval approval=approval(set,Collections.<String>emptySet());ApplyResult result=writer.apply(applyWorkspace,set,approval);assertEquals(ApplyState.APPLIED,result.getState());assertEquals(ApplyState.APPLIED,writer.apply(applyWorkspace,set,approval).getState());assertEquals("new",read(root.resolve("a.txt")));assertTrue(Files.isRegularFile(Paths.get(result.getFiles().get(0).getBackupPath())));assertEquals(set.getPreviewDigest(),preview.getPreviewDigest());assertTrue(Files.isRegularFile(root.resolve(".clara/staging/run/"+set.getChangeSetId()+"-r1/journal.bin")));}
 @Test public void requiresApplyModeAndExactApprovalDigest()throws Exception{Files.write(root.resolve("a.txt"),"old".getBytes(StandardCharsets.UTF_8));final ChangeSet set=replace(previewWorkspace,"old","new");final FileSystemWorkspaceWriter writer=new FileSystemWorkspaceWriter(policy);assertCode(ErrorCodes.WORKSPACE_ACCESS_DENIED,new Runnable(){public void run(){writer.apply(previewWorkspace,set,approval(set,Collections.<String>emptySet()));}});final Approval wrong=new Approval(set.getChangeSetId(),set.getRevision(),set.getDigest(),"wrong","user",1L,Collections.<String>emptySet());assertCode(ErrorCodes.CHANGESET_APPROVAL_INVALID,new Runnable(){public void run(){writer.apply(applyWorkspace,set,wrong);}});}
 @Test public void rejectsExternallyModifiedBaseline()throws Exception{Files.write(root.resolve("a.txt"),"old".getBytes(StandardCharsets.UTF_8));final ChangeSet set=replace(previewWorkspace,"old","new");Files.write(root.resolve("a.txt"),"external".getBytes(StandardCharsets.UTF_8));final FileSystemWorkspaceWriter writer=new FileSystemWorkspaceWriter(policy);assertCode(ErrorCodes.WORKSPACE_CONFLICT,new Runnable(){public void run(){writer.apply(applyWorkspace,set,approval(set,Collections.<String>emptySet()));}});assertEquals("external",read(root.resolve("a.txt")));}
 @Test public void previewRejectsInternalAndNonCanonicalPaths()throws Exception{Files.write(root.resolve("a.txt"),"old".getBytes(StandardCharsets.UTF_8));ChangeSet valid=replace(previewWorkspace,"old","new");FileChange original=valid.getChanges().get(0);final FileSystemWorkspaceWriter writer=new FileSystemWorkspaceWriter(policy);final ChangeSet alias=setWith(new FileChange("folder/../a.txt",original.getBaseHash(),original.getResultHash(),original.getContent()));assertCode(ErrorCodes.WORKSPACE_ACCESS_DENIED,new Runnable(){public void run(){writer.preview(previewWorkspace,alias);}});final ChangeSet internal=setWith(new FileChange(".clara/state.txt",original.getBaseHash(),original.getResultHash(),original.getContent()));assertCode(ErrorCodes.WORKSPACE_ACCESS_DENIED,new Runnable(){public void run(){writer.preview(previewWorkspace,internal);}});}
 @Test public void rollsBackPartialFailureAndRecoveryUsesHashes()throws Exception{Files.write(root.resolve("a.txt"),"x".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("b.txt"),"x".getBytes(StandardCharsets.UTF_8));final ChangeSet set=replace(previewWorkspace,"x","y");FileSystemWorkspaceWriter.AtomicMover failing=new FileSystemWorkspaceWriter.AtomicMover(){private int calls;public void move(Path source,Path target)throws IOException{calls++;if(calls>=2)throw new IOException("simulated");Files.move(source,target,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}};FileSystemWorkspaceWriter writer=new FileSystemWorkspaceWriter(policy,failing);ApplyResult failed=writer.apply(applyWorkspace,set,approval(set,Collections.<String>emptySet()));assertEquals(ApplyState.PARTIALLY_APPLIED,failed.getState());assertEquals("y",read(root.resolve("a.txt")));assertEquals("x",read(root.resolve("b.txt")));ApplyResult recovered=new FileSystemWorkspaceWriter(policy).recover(applyWorkspace,"run",set.getChangeSetId(),1);assertEquals(ApplyState.ROLLED_BACK,recovered.getState());assertEquals("x",read(root.resolve("a.txt")));assertEquals("x",read(root.resolve("b.txt")));}
 private ChangeSet replace(WorkspaceRef workspace,String from,String to){TextSearchRequest request=new TextSearchRequest(TextMatchMode.LITERAL,from,false,20,20);TextSearchResult found=text.search(workspace,request);return text.replace(workspace,new TextEditSpec(request,TextEditAction.REPLACE_MATCH,to,Collections.<String>emptySet(),found.getMatches().size(),20));}
 private static ChangeSet setWith(FileChange change){List<FileChange> changes=Collections.singletonList(change);String digest=WorkspaceDigests.changes(changes),preview=WorkspaceDigests.preview(changes);return new ChangeSet("cs-test","run",1,digest,preview,changes);}
 private static Approval approval(ChangeSet set,Set<String> paths){return new Approval(set.getChangeSetId(),set.getRevision(),set.getDigest(),set.getPreviewDigest(),"user",1L,paths);}
 private static String read(Path path)throws IOException{return new String(Files.readAllBytes(path),StandardCharsets.UTF_8);}
 private static void assertCode(String code,Runnable action){try{action.run();fail("expected "+code);}catch(ClaraException e){assertEquals(code,e.getError().getCode());}}
}
